import{_ as o,l as i,o as e,c as l,v as t,p as A,x as r,d as n,i as c,S as C}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CSMA/CA 无线对照","description":"","frontmatter":{"title":"CSMA/CA 无线对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csma-ca.md","filePath":"cs/csma-ca.md","lastUpdated":1789023840000}'),d={name:"cs/csma-ca.md"};function p(h,a,m,_,E,S){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="csma-ca-无线对照" tabindex="-1">CSMA/CA 无线对照 <a class="header-anchor" href="#csma-ca-无线对照" aria-label="Permalink to &quot;CSMA/CA 无线对照&quot;">​</a></h1><div class="epigraph"><p>无线往往不能边发边听自己的冲突；改成发前避让，并用预约把隐藏终端的碰撞推开。</p><footer>—— 据 IEEE 802.11；Kurose and Ross 对 CSMA/CA 与隐藏终端的整理</footer></div><p><a href="/cs/csma-switch">上一课</a>在有线共享介质上用 CSMA/CD，又用交换机把冲突域收到端口。本课不重讲 MAC 学习。缺口是无线：同一信道上仍要多址，但发送机自己的信号淹没接收，<strong>冲突检测（CD）做不成</strong>。对照是 CSMA/CA：避让代替边听。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有线 CD 假设：发送时仍能从介质上听出别人的能量。无线收发隔离困难，而且「我听不见你」不等于「目的听不见你」——隐藏终端。若仍按以太网那样抢完再靠 FCS 发现，碰撞浪费整帧空气时间。缺口是访问方法换成<strong>冲突避免</strong>，不是新的 IP。</p><p><span class="marginnote">隐藏终端：A 与 C 都听不见对方，却都能让 B 处碰撞。暴露终端是对偶：听见别人并不等于自己发送会破坏那次接收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CSMA/CA：发前听信道；忙则随机退避。可选 RTS/CTS：短控制帧让周围节点设置 NAV，在一段时间内不发，把信道当预约。确认仍常要显式 ACK，因为单向听到的「能量」不等于对端收对。本课不把 802.11 全部帧类型与速率自适应写成标准正文。</p>',8)),(e(),A(C,null,{default:r(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LISTEN%5B%22%E5%8F%91%E5%89%8D%E5%90%AC%22%5D%20--%3E%20BACK%5B%22%E5%BF%99%E5%88%99%E9%80%80%E9%81%BF%22%5D%0A%20%20BACK%20--%3E%20RTS%5B%22%E5%8F%AF%E9%80%89%20RTS%2FCTS%20%E9%A2%84%E7%BA%A6%22%5D%0A%20%20RTS%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E5%B8%A7%22%5D%0A%20%20DATA%20--%3E%20ACK%5B%22%E5%AF%B9%E7%AB%AF%20ACK%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CA 把碰撞从「发到一半发现」改成「尽量别同时发」。交换机那一套学源 MAC、缩小冲突域，在无线接入点上变成基础结构模式：站点经 AP 转发，但空口仍是共享介质。FCS（<a href="/cs/frame-crc">上一课的 CRC</a>）照旧丢坏帧；避让只降低碰撞概率。端到端可靠性仍不在这一层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入蜂窝调度与 TDMA 主干，不把蓝牙跳频当 802.11。全双工有线交换口上已经不用 CA；不要把无线退避抄回数据中心以太网当默认。生成树处理的是有线环路，下一课，不是隐藏终端。</p><p>后课默认：共享空气用避让与预约。有线交换网里广播域仍可能环，下一课生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线难做 CD，CSMA/CA 用听、退避与可选预约。</li><li>隐藏终端是几何问题，不是 CRC 多项式选错。</li><li>有线环路是另一缺口，下一课生成树。</li><li>出处：IEEE 802.11；Kurose and Ross。</li></ul>',7))])}const f=o(d,[["render",p]]);export{u as __pageData,f as default};
